"""Create-only upload of reviewed R33 inputs, then exec its first qualifier."""
import base64, hashlib, json, os, sys
from pathlib import Path
ROOT = Path('/home/qian/hepta-runtime-optimization-20261106-r33')
PAYLOAD = [{'path': 'prepare_qualify.py', 'bytes': 25125, 'sha256': 'c1e6ef1bf6d4a1c42a644a220ab00a5b14b95281e76e24f94526d367a07f351d', 'base64': ''}, {'path': 'input.json', 'bytes': 52436, 'sha256': '3753078ae1fa3dd7c9b2582d2d5a6e01335937b6651c5094314955e16b1af48d', 'base64': ''}, {'path': 'combined.patch', 'bytes': 11652, 'sha256': 'a6ec7d9f3f75647eed0d421ba69de20cb504cf369c2dde4752ca19f1004133f5', 'base64': ''}, {'path': 'chain-proof.json', 'bytes': 2776, 'sha256': 'c93aa390e8f6f2d9d4175f4dd8ed1474a94e8f2d7466b1b19d3f9bc304810b32', 'base64': ''}, {'path': 'cache-owner-closure-inputs.json', 'bytes': 3918, 'sha256': 'd10e468c67c21691fd6cb77d080aa589430c30c61accb12482004d4b10cf0353', 'base64': ''}, {'path': 'chain/r32/candidate.patch', 'bytes': 2946, 'sha256': 'f009b618afb5dd574ef9d0b1bf2d73ecd108e2882779a05862ebafee9bc5019a', 'base64': ''}, {'path': 'chain/r32/input.json', 'bytes': 49713, 'sha256': 'ed47cc74d4189fa0941192846f2ce4e8e2103954c4a3b4636fd1aab69a774a00', 'base64': ''}, {'path': 'chain/r32/manifest.json', 'bytes': 4631, 'sha256': 'e1969d047545c70a857c733f3318b0c33140a3a8b6b0b85c2505f8457282985a', 'base64': ''}, {'path': 'chain/r33/candidate.patch', 'bytes': 9507, 'sha256': '05472a554635d415bbafd4b2119c09d88696e90f4e0003cf81cfa8da9271b4d0', 'base64': ''}, {'path': 'chain/r33/baseline-overlay.patch', 'bytes': 2946, 'sha256': 'f009b618afb5dd574ef9d0b1bf2d73ecd108e2882779a05862ebafee9bc5019a', 'base64': ''}, {'path': 'chain/r33/input.json', 'bytes': 50729, 'sha256': '46ff8e0cc8327fa97e346acd8afa8c6ab7ef2ffc40e8d2b75d221d4101d9b1f5', 'base64': ''}, {'path': 'chain/r33/manifest.json', 'bytes': 7100, 'sha256': '4da10500f9108f484c4415ec726776685f61bfc73eccf7a12b23fed3f7ab53d5', 'base64': ''}, {'path': 'package-manifest.json', 'bytes': 4127, 'sha256': 'aaabf3c54ec60e527688d2492c9d0ebe076d98b5e59911c72214c1b11319bbb6', 'base64': ''}]
assert sys.platform == 'linux' and os.getuid() == 1000
assert ROOT.parent.resolve(strict=True) == ROOT.parent
assert not os.path.lexists(ROOT), 'preserve an existing R33 preparation namespace'
assert len(PAYLOAD) == 13 and len({x['path'] for x in PAYLOAD}) == 13
prepared = []
for item in PAYLOAD:
    p = Path(item['path'])
    assert not p.is_absolute() and '..' not in p.parts and str(p) == item['path']
    b = base64.b64decode(item['base64'], validate=True)
    assert len(b) == item['bytes'] and hashlib.sha256(b).hexdigest() == item['sha256']
    prepared.append((p, b, {k: item[k] for k in ('path','bytes','sha256')}))
assert sum(len(b) for _, b, _ in prepared) == 227606
ROOT.mkdir(mode=0o700)
for p, b, pin in prepared:
    target = ROOT / p
    target.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    assert target.parent.resolve(strict=True) == target.parent
    with target.open('xb') as stream:
        stream.write(b); stream.flush(); os.fsync(stream.fileno())
    assert target.stat().st_nlink == 1 and target.read_bytes() == b
receipt = {'schema':'hepta-r33-qualification-input-upload/v1', 'created_only':True,
           'files':[pin for _,_,pin in prepared], 'qualification_started':False,
           'automatic_retries':0, 'root':str(ROOT)}
with (ROOT / 'input-upload-receipt.json').open('x') as stream:
    json.dump(receipt,stream,sort_keys=True,indent=2); stream.write('\n'); stream.flush(); os.fsync(stream.fileno())
print(json.dumps({'phase':'r33_reviewed_inputs_uploaded','files':len(prepared),'bytes':227606,'qualification_started':False}),flush=True)
os.execv('/usr/bin/python3', ['/usr/bin/python3','-B','-u',str(ROOT/'prepare_qualify.py'),
    '--input-sha256','3753078ae1fa3dd7c9b2582d2d5a6e01335937b6651c5094314955e16b1af48d',
    '--owner-closure-sha256','d10e468c67c21691fd6cb77d080aa589430c30c61accb12482004d4b10cf0353'])
